Future<AdminCounterFormResult?> showAdminCounterFormDialog({required BuildContext context, required bool isSubmitting, required String stationName, StructuredApiError? error, AdminStationCounter? initialCounter, AdminStationCounterCreateRequest? initialCreateRequest, AdminStationCounterUpdateRequest? initialUpdateRequest}) => showDialog<AdminCounterFormResult>(context: context, useSafeArea: true, barrierDismissible: !isSubmitting, builder: (dialogContext) { final size = MediaQuery.sizeOf(dialogContext); final content = AdminCounterFormDialog(isSubmitting: isSubmitting, stationName: stationName, error: error, initialCounter: initialCounter, initialCreateRequest: initialCreateRequest, initialUpdateRequest: initialUpdateRequest); if (size.width < 640) return Dialog.fullscreen(child: SafeArea(child: content)); return Dialog(clipBehavior: Clip.antiAlias, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)), child: SizedBox(width: size.width > 560 ? 520 : size.width - 32, height: size.height > 520 ? 460 : size.height * 0.9, child: content)); });

