: widget.isSubmitting ? null : _submit, icon: widget.isSubmitting ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2)) : Icon(_isEdit ? Icons.save_outlined : Icons.add), label: Text(_isEdit ? 'Enregistrer' : 'Créer'))]))])); void _submit() { if (!_formKey.currentState!.validate()) return; if (_isEdit) { final c = widget.initialCounter!; Navigator.pop(context, AdminCounterFormResult.update(AdminStationCounterUpdateRequest(code: _changedText(_codeController.text, c.code), label: _changedText(_labelController.text, c.label)))); return; } Navigator.pop(context, AdminCounterFormResult.create(AdminStationCounterCreateRequest(code: _codeController.text, label: _labelController.text))); } String? _changedText(String current, String? initial) { final trimmed = current.trim(); if (trimmed == (initial ?? '').trim()) return null; return trimmed; } }
